    return edges

def gaussian_elimination(matrix):
    m, n = len(matrix), len(matrix[0])
    rank = 0
    for i in range(n):
        pivot = None
        for j in range(rank, m):
            if matrix[j][i] != 0:
                pivot = j
                break
        if pivot is None:
            continue
        matrix[pivot], matrix[rank] = matrix[rank], matrix[pivot]
        for j in range(n):
